/*
 * INV-07 — Panel de lista de exclusión.
 * Ningún color literal: todo sale del vocabulario de tokens (`var(--bw-*)`).
 *
 * Nota de tokens: los campos del HTML aprobado van sobre blanco puro; el vocabulario
 * cerrado no tiene token de blanco, así que los campos usan el neutro más claro
 * disponible (`--bw-cold-white`) y los bordes de control `--bw-line-steel-strong`.
 */

.panel {
  display: flex;
  flex-direction: column;
  transition: opacity 0.2s;
}

/* En modo abierto (o sin permiso) el panel queda inerte pero visible. */
.panel[data-active='false'] {
  opacity: 0.55;
}

.panel[data-active='false'] .tagLabel {
  color: var(--bw-steel-mist);
}

.section {
  margin-bottom: 22px;
}

.section:last-of-type {
  margin-bottom: 0;
}

.sectionTitle {
  margin: 0 0 10px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-label);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-ink-steel);
}

.search {
  width: 100%;
  padding: var(--bw-pad-input);
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 6px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s;
}

.search:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.search::placeholder {
  color: var(--bw-input-placeholder);
}

.search:disabled {
  background: var(--bw-surface-mist);
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.hint {
  margin: 6px 0 0;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
  color: var(--bw-input-placeholder);
}

.candidates {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.candidate {
  padding: 6px 10px;
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-deep-steel);
  cursor: pointer;
  transition: border-color 0.12s, background 0.12s, color 0.12s;
}

.candidate:hover {
  background: var(--bw-chip-active-bg);
  border-color: var(--bw-chip-active-border);
  color: var(--bw-primary-dark);
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  background: var(--bw-chip-active-bg);
  border: 1px solid var(--bw-chip-active-border);
  border-radius: 20px;
}

.tagGeo {
  background: var(--bw-tag-bg);
  border-color: var(--bw-tag-border);
}

.tagLabel {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.tagRemove {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  background: none;
  border: none;
  font-family: inherit;
  font-size: var(--bw-size-input);
  line-height: 1;
  color: var(--bw-steel-mist);
  cursor: pointer;
  transition: color 0.12s;
}

.tagRemove:hover:not(:disabled) {
  color: var(--bw-danger-light);
}

.tagRemove:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.geoRow {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 10px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  flex: 1;
  min-width: 180px;
}

.fieldLabel {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-ink-steel);
}

.select {
  padding: var(--bw-pad-input);
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 6px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  cursor: pointer;
  transition: border-color 0.15s;
}

.select:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
  outline: none;
}

.select:disabled {
  background: var(--bw-surface-mist);
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.addGeo {
  height: 36px;
  margin-top: 10px;
  padding: 0 14px;
  background: var(--bw-deep-steel);
  border: none;
  border-radius: 6px;
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
  transition: opacity 0.12s;
}

.addGeo:hover:not(:disabled) {
  opacity: 0.85;
}

.addGeo:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.error {
  margin: 16px 0 0;
  padding: 10px 14px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-error-text);
}

import type { Zone } from '../../lib/search';
import {
  CONTINENT_OPTIONS,
  type CountryOption,
  type Exclusion,
  type OrgCandidate,
} from '../../lib/visibility';
import styles from './ExclusionPanel.module.css';

interface Props {
  /** Etiquetas de exclusión por organización (ya agrupadas y ordenadas por la pantalla). */
  orgs: Exclusion[];
  /** Etiquetas geográficas: continentes y países juntos. */
  geo: Exclusion[];
  /** Candidatos del autocompletado, ya filtrados por `filterOrgCandidates`. */
  candidates: OrgCandidate[];
  query: string;
  continent: Zone | '';
  country: string;
  countries: CountryOption[];
  /** Modo abierto o miembro sin permiso: el panel queda inerte pero visible. */
  disabled: boolean;
  /** Hay una escritura en vuelo. */
  busy: boolean;
  /** Error de la última acción de exclusión; se pinta dentro del panel. */
  error: string | null;
  onQueryChange: (q: string) => void;
  onPickOrg: (c: OrgCandidate) => void;
  onContinentChange: (c: Zone | '') => void;
  onCountryChange: (code: string) => void;
  onAddGeo: () => void;
  onRemove: (e: Exclusion) => void;
}

const ORG_SECTION_LABEL = 'Exclusión por organización';
const GEO_SECTION_LABEL = 'Exclusión por geografía';
const ORG_HINT = 'EFECTO INMEDIATO AL AÑADIR';
const GEO_HINT = 'EXCLUYE TODAS LAS ORGANIZACIONES CON SEDE EN ESA GEOGRAFÍA';

/**
 * INV-07 — Panel de lista de exclusión. Presentacional puro: sin red y sin estado
 * propio (`query`, `continent` y `country` llegan por props y los cambios se
 * devuelven hacia arriba). Las exclusiones tienen efecto inmediato, así que aquí no
 * hay ningún botón de guardado.
 */
export function ExclusionPanel({
  orgs,
  geo,
  candidates,
  query,
  continent,
  country,
  countries,
  disabled,
  busy,
  error,
  onQueryChange,
  onPickOrg,
  onContinentChange,
  onCountryChange,
  onAddGeo,
  onRemove,
}: Props) {
  /** `disabled` y `busy` bloquean lo mismo en las etiquetas ya puestas. */
  const removeDisabled = disabled || busy;

  /*
   * El refinador de país aparece en cuanto hay continente elegido, aunque la lista de
   * países siga en vuelo: su primera opción («Todos los países del continente») es
   * una elección válida por sí sola — excluye el continente entero — y no depende de
   * la carga. `countries` solo añade opciones cuando llega.
   */
  const showCountry = continent !== '';

  return (
    <div
      className={styles.panel}
      data-testid="exclusion-panel"
      data-active={disabled ? 'false' : 'true'}
    >
      <section className={styles.section} aria-label={ORG_SECTION_LABEL}>
        <h2 className={styles.sectionTitle}>{ORG_SECTION_LABEL}</h2>

        <input
          className={styles.search}
          type="text"
          placeholder="Buscar organización por nombre..."
          value={query}
          disabled={disabled}
          onChange={(e) => onQueryChange(e.target.value)}
        />
        <p className={styles.hint}>{ORG_HINT}</p>

        {/* Sin candidatos no hay lista: ni vacía ni con un «no hay resultados». */}
        {candidates.length > 0 && (
          <ul className={styles.candidates} aria-label="Organizaciones candidatas">
            {candidates.map((candidate) => (
              <li key={candidate.id}>
                <button
                  type="button"
                  className={styles.candidate}
                  onClick={() => onPickOrg(candidate)}
                >
                  {candidate.name}
                </button>
              </li>
            ))}
          </ul>
        )}

        <ul className={styles.tags} aria-label="Organizaciones excluidas">
          {orgs.map((exclusion) => (
            <li key={exclusion.id} className={styles.tag}>
              <span className={styles.tagLabel}>{exclusion.label}</span>
              <button
                type="button"
                className={styles.tagRemove}
                aria-label={`Quitar ${exclusion.label}`}
                disabled={removeDisabled}
                onClick={() => onRemove(exclusion)}
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section className={styles.section} aria-label={GEO_SECTION_LABEL}>
        <h2 className={styles.sectionTitle}>{GEO_SECTION_LABEL}</h2>

        <div className={styles.geoRow}>
          <label className={styles.field}>
            <span className={styles.fieldLabel}>Excluir por continente</span>
            <select
              className={styles.select}
              value={continent}
              disabled={disabled}
              onChange={(e) => onContinentChange(e.target.value as Zone | '')}
            >
              <option value="">Selecciona un continente</option>
              {CONTINENT_OPTIONS.map((option) => (
                <option key={option.code} value={option.code}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>

          {showCountry && (
            <label className={styles.field}>
              <span className={styles.fieldLabel}>Refinar por país</span>
              <select
                className={styles.select}
                value={country}
                disabled={disabled}
                onChange={(e) => onCountryChange(e.target.value)}
              >
                <option value="">Todos los países del continente</option>
                {countries.map((option) => (
                  <option key={option.code} value={option.code}>
                    {option.label}
                  </option>
                ))}
              </select>
            </label>
          )}
        </div>

        <button
          type="button"
          className={styles.addGeo}
          disabled={disabled || busy || continent === ''}
          onClick={onAddGeo}
        >
          Añadir exclusión geográfica
        </button>
        <p className={styles.hint}>{GEO_HINT}</p>

        <ul className={styles.tags} aria-label="Exclusiones geográficas">
          {geo.map((exclusion) => (
            <li key={exclusion.id} className={`${styles.tag} ${styles.tagGeo}`}>
              <span className={styles.tagLabel}>{exclusion.label}</span>
              <button
                type="button"
                className={styles.tagRemove}
                aria-label={`Quitar ${exclusion.label}`}
                disabled={removeDisabled}
                onClick={() => onRemove(exclusion)}
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      </section>

      {error !== null && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

