 * `--bw-surface-mist` para la superficie de tarjeta y `--bw-warm-cream` para el texto
 * sobre fondo de acción.
 */

/*
 * La pantalla es hija DIRECTA de `.bwcnt` (`overflow: hidden`): sin su propio scroll
 * el contenido se recortaría en ventanas bajas (F-186/F-189/F-190/F-198).
 */
.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.eyebrow {
  margin-bottom: 6px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
