import { useEffect, useState } from 'react';
import type { Zone } from '../../lib/search';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  addExclusion,
  canManageVisibility,
  DEFAULT_VISIBILITY_MODE,
  fetchContinentCountries,
  fetchOrgCandidates,
  fetchVisibility,
  filterOrgCandidates,
  groupExclusions,
  IMMEDIATE_EFFECT_NOTICE,
  KEPT_LIST_NOTICE,
  READ_ONLY_NOTICE,
  removeExclusion,
  SAVED_MESSAGE,
  saveVisibilityMode,
  VISIBILITY_MODES,
  type CountryOption,
  type Exclusion,
  type OrgCandidate,
  type VisibilityMode,
} from '../../lib/visibility';
import { ExclusionPanel } from './ExclusionPanel';
import styles from './Visibility.module.css';

const EYEBROW = 'Módulo 02 · Gestión de Inventario';
const TITLE = 'Visibilidad del inventario';
const SUBTITLE =
  'Controla quién puede ver tu stock en Bearingworld.io. El modo se aplica a todo tu inventario de forma inmediata.';
const MODE_LEGEND = 'Modo de visibilidad';

/**
 * INV-07 — Configuración de Visibilidad del Inventario.
 *
 * La pantalla posee TODO el estado: el modo GUARDADO, el modo del radio (borrador),
 * la lista de exclusiones, el directorio de organizaciones para el autocompletado y
 * los países del continente elegido. `ExclusionPanel` es presentacional.
 *
 * La carga de `fetchVisibility` y `fetchOrgCandidates` ocurre UNA sola vez al montar;
 * a partir de ahí, lo único que vuelve a leer la lista son las tres acciones de
 * exclusión (añadir organización, añadir geografía, quitar), que tienen efecto
 * inmediato y no pasan por `Guardar configuración`.
 */
export function Visibility({ profile }: { profile: MemberProfile }) {
  const canManage = canManageVisibility(profile.role);

  /** El modo tal y como está en la base: cambia solo cuando `Guardar` va bien. */
  const [savedMode, setSavedMode] = useState<VisibilityMode>(DEFAULT_VISIBILITY_MODE);
  /** El modo del radio. Cambiar de radio NO llama a la red: solo mueve el borrador. */
  const [draftMode, setDraftMode] = useState<VisibilityMode>(DEFAULT_VISIBILITY_MODE);
  const [exclusions, setExclusions] = useState<Exclusion[]>([]);
  /** El directorio completo: el filtrado de candidatos es puro y de cliente. */
  const [directory, setDirectory] = useState<OrgCandidate[]>([]);

  const [loadError, setLoadError] = useState<string | null>(null);
  /** Error de una acción de exclusión: viaja en la prop `error` del panel. */
  const [panelError, setPanelError] = useState<string | null>(null);
  /** Error de `Guardar configuración`. */
  const [saveError, setSaveError] = useState<string | null>(null);
  /** Aviso de éxito: uno solo a la vez, `role="status"`. */
  const [notice, setNotice] = useState<string | null>(null);
  /** Hay una escritura de exclusión en vuelo. */
  const [busy, setBusy] = useState(false);

  const [query, setQuery] = useState('');
  const [continent, setContinent] = useState<Zone | ''>('');
  const [country, setCountry] = useState('');
  const [countries, setCountries] = useState<CountryOption[]>([]);

  useEffect(() => {
    let active = true;

    fetchVisibility(profile.orgId)
      .then((state) => {
        if (!active) return;
        setSavedMode(state.mode);
        // El borrador del radio arranca igual que el modo guardado.
        setDraftMode(state.mode);
        setExclusions(state.exclusions);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
      });

    fetchOrgCandidates()
      .then((list) => {
        if (!active) return;
        setDirectory(list);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
      });

    return () => {
      active = false;
    };
    // Solo `orgId`: `profile` cambia de identidad en cada render y no queremos
    // volver a pedir la lista en cada uno.
  }, [profile.orgId]);

  /** Repide la lista tras una acción de exclusión que ha ido bien. NO toca el modo. */
  async function reloadExclusions(): Promise<void> {
    const state = await fetchVisibility(profile.orgId);
    setExclusions(state.exclusions);
  }

  /**
   * Añadir organización: efecto inmediato. El buscador solo se vacía si la escritura
   * fue bien; si falla, el mensaje va al panel y la lista NO se repide.
   */
  async function handlePickOrg(candidate: OrgCandidate): Promise<void> {
    setBusy(true);
    setPanelError(null);
    try {
      await addExclusion(profile.orgId, { orgId: candidate.id });
      await reloadExclusions();
      setQuery('');
    } catch (e: unknown) {
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  /**
   * Cambiar de continente guarda el continente, vacía el país y pide sus países.
   * Es una lectura de apoyo, no una escritura: el botón de añadir geografía no
   * depende de ella, así que no marca `busy`.
   */
  function handleContinentChange(code: Zone | ''): void {
    setContinent(code);
    setCountry('');
    setCountries([]);
    setPanelError(null);
    if (code === '') return;

    fetchContinentCountries(code)
      .then((list) => setCountries(list))
      .catch((e: unknown) => setPanelError(errorMessage(e)));
  }

  /**
   * Añadir geografía: país si hay uno elegido, continente si no. Efecto inmediato.
   * Solo limpia continente y país si la escritura fue bien.
   */
  async function handleAddGeo(): Promise<void> {
    if (country === '' && continent === '') return;

    setBusy(true);
    setPanelError(null);
    try {
      if (country !== '') await addExclusion(profile.orgId, { country });
      else if (continent !== '') await addExclusion(profile.orgId, { continent });
      await reloadExclusions();
      setContinent('');
      setCountry('');
      setCountries([]);
    } catch (e: unknown) {
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  /** Quitar una exclusión: efecto inmediato. Si falla, la etiqueta sigue donde estaba. */
  async function handleRemove(exclusion: Exclusion): Promise<void> {
    setBusy(true);
    setPanelError(null);
    try {
      await removeExclusion(exclusion.id);
      await reloadExclusions();
    } catch (e: unknown) {
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  /** `Guardar configuración`: guarda SOLO el modo. La lista ya se escribió al momento. */
  async function handleSave(): Promise<void> {
    setNotice(null);
    setSaveError(null);
    try {
      await saveVisibilityMode(profile.orgId, draftMode);
      setSavedMode(draftMode);
      setNotice(SAVED_MESSAGE);
    } catch (e: unknown) {
      // Sin aviso de éxito: solo el error.
      setSaveError(errorMessage(e));
    }
  }

  const { orgs, geo } = groupExclusions(exclusions);
  const candidates = filterOrgCandidates(directory, query, exclusions, profile.orgId);
  const showPanel = draftMode === 'RESTRINGIDA' || exclusions.length > 0;
  const panelDisabled = draftMode === 'VISIBLE_TODOS' || !canManage;

  return (
    <div className={styles.screen}>
      <div className={styles.eyebrow}>{EYEBROW}</div>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {loadError !== null && (
        <p className={styles.alert} role="alert">
          {loadError}
        </p>
      )}

      {/* ── Selector de modo: el radio solo mueve el borrador, no llama a la red. ── */}
      <div className={styles.card}>
        <fieldset
          className={styles.fieldset}
          role="radiogroup"
          aria-label={MODE_LEGEND}
          data-saved-mode={savedMode}
        >
          <legend className={styles.legend}>{MODE_LEGEND}</legend>
          <div className={styles.radios}>
            {VISIBILITY_MODES.map((mode) => (
              <label
                key={mode.value}
                className={
                  draftMode === mode.value ? `${styles.radio} ${styles.radioActive}` : styles.radio
                }
              >
                <input
                  className={styles.radioInput}
                  type="radio"
                  name="visibility-mode"
                  value={mode.value}
                  checked={draftMode === mode.value}
                  disabled={!canManage}
                  onChange={() => setDraftMode(mode.value)}
                />
                <span className={styles.radioText}>
                  <span className={styles.radioLabel}>{mode.label}</span>
                  <span className={styles.radioDesc}>{mode.description}</span>
                </span>
              </label>
            ))}
          </div>
        </fieldset>

        {/* La lista se conserva: solo se desactiva mientras el modo está abierto. */}
        {draftMode === 'VISIBLE_TODOS' && exclusions.length > 0 && (
          <p className={styles.brassNotice}>{KEPT_LIST_NOTICE}</p>
        )}
      </div>

      {/* ── Panel de exclusión: sin panel no hay aviso que valga. ── */}
      {showPanel && (
        <div className={styles.card}>
          <ExclusionPanel
            orgs={orgs}
            geo={geo}
            candidates={candidates}
            query={query}
            continent={continent}
            country={country}
            countries={countries}
            disabled={panelDisabled}
            busy={busy}
            error={panelError}
            onQueryChange={setQuery}
            onPickOrg={handlePickOrg}
            onContinentChange={handleContinentChange}
            onCountryChange={setCountry}
            onAddGeo={handleAddGeo}
            onRemove={handleRemove}
          />
        </div>
      )}

      <div className={styles.brassBlock}>
        <p className={styles.brassText}>{IMMEDIATE_EFFECT_NOTICE}</p>
      </div>

      {!canManage && <p className={styles.readOnly}>{READ_ONLY_NOTICE}</p>}

      <div className={styles.actions}>
        <button
          type="button"
          className={styles.save}
          disabled={!canManage}
          onClick={() => {
            void handleSave();
          }}
        >
          Guardar configuración
        </button>
      </div>

      {notice !== null && (
        <p className={styles.status} role="status">
          {notice}
        </p>
      )}

      {saveError !== null && (
        <p className={styles.alert} role="alert">
          {saveError}
        </p>
      )}
    </div>
  );
}
